using System;
using System.Collections.Generic;
using System.Linq;
namespace MaritimeLegend.Domain {
public partial class GameService : IMarketService,IProductionService {
        public MarketEntry Market(int city,string p){return S.cities[city].market.First(x=>x.product==p);}
        public double Specialty(int city,Product p){return C.ports[city].raw.Contains(p.id)?C.balance.economy.localPriceFactor:C.balance.economy.foreignPriceFactor+(city+p.industry)%C.balance.economy.specialtyBands*C.balance.economy.specialtyBandStep;}
        int Price(int city,Product p,int q,bool buy,double pressure){return GameFormulas.MarketPrice(C,p,q,Specialty(city,p),pressure,buy);}
        public int Quote(int city,string p,int q,bool buy){return Price(city,C.Product(p),q,buy,Market(city,p).pressure);}
        public int Preview(int city,string id,int q,int n,bool buy){var m=Market(city,id);double p=m.pressure;int total=0;for(int i=0;i<n;i++){total+=Price(city,C.Product(id),q,buy,p);p=Clamp(p+(buy?1:-1)*C.market.pressureStep/C.market.referenceStock,C.market.pressureMin,C.market.pressureMax);}return total;}
        public string Trade(int city,string id,int q,int n,bool buy,Inventory inv){if(city<0||city>=C.ports.Length||q<0||q>=C.market.qualityFactors.Length||n<1||n>C.balance.economy.maxTradeQuantity)return "交易参数无效";var p=C.Product(id);var m=Market(city,id);if(buy&&m.Stock(q)<n)return "城市库存不足";if(!buy&&Inventory.Count(inv,id,q)<n)return "你的库存不足";if(buy&&Inventory.Weight(inv)+p.weight*n>inv.capacity)return "容量不足";if(!buy&&m.stock+n>C.market.maxStock)return "市场已饱和，请换港销售";int total=Preview(city,id,q,n,buy);if(buy&&S.gold<total)return "金币不足";if(buy){S.gold-=total;m.ChangeStock(q,-n);Inventory.Add(inv,id,q,n,city);m.bought+=n;}else{Inventory.Take(inv,id,n,q);S.gold+=total;m.ChangeStock(q,n);m.sold+=n;}m.pressure=Clamp(m.pressure+(buy?1:-1)*n*C.market.pressureStep/C.market.referenceStock,C.market.pressureMin,C.market.pressureMax);S.trades++;S.cities[city].reputation+=Math.Max(1,n/C.balance.economy.unitsPerReputation);Gain(C.balance.skills.tradeSkill,Math.Min(n,C.balance.economy.maxTradeExperience));Emit("trade");if(m.stock<C.balance.economy.shortageThreshold)Emit("shortage");CheckQuest();return (buy?"购入":"售出")+p.name+" ×"+n+"，"+(buy?"支出":"收入")+total+" 金币";}
        public void MarketHour(){foreach(var cs in S.cities)foreach(var m in cs.market){m.pressure*=Math.Pow(1-C.market.dailyReversion,1.0/C.balance.world.hoursPerDay);var p=C.Product(m.product);if(p.category=="R"&&C.ports[cs.id].raw.Contains(p.id))m.ChangeStock(C.initial.creation.starterMaterialQuality,Math.Max(0,Math.Min(C.balance.economy.rawHourlySupply,(int)C.market.maxStock-m.stock)));else if(p.category=="R"&&!C.ports[cs.id].raw.Contains(p.id)){int remaining=C.balance.economy.foreignRawHourlyConsumption;for(int q=C.market.qualityFactors.Length-1;q>=0&&remaining>0;q--){int take=Math.Min(remaining,m.Stock(q));m.ChangeStock(q,-take);remaining-=take;}}else if(p.category!="R"&&p.id!=C.objectives.instrument){if(m.stock<C.balance.economy.processedStockTarget)m.ChangeStock(C.balance.economy.processedSupplyQuality,Math.Max(0,Math.Min(C.balance.economy.processedHourlySupply,Math.Min(C.balance.economy.processedStockTarget,(int)C.market.maxStock)-m.stock)));else if(m.stock>C.balance.economy.processedStockTarget){for(int q=C.market.qualityFactors.Length-1;q>=0;q--)if(m.Stock(q)>0){m.ChangeStock(q,-1);break;}}}}}
        public string Contract(){if(S.worldHours>S.contractDeadline){S.contractProduct=(S.contractProduct+C.balance.economy.contractProductStep)%C.products.Length;S.contractDeadline=S.worldHours+C.balance.economy.contractHours;return "委托已更新，请查看新货物";}var p=C.products[S.contractProduct];if(Inventory.Count(S.cargo,p.id)<S.contractQuantity)return "船舱中需要 "+p.name+" ×"+S.contractQuantity;Inventory.Take(S.cargo,p.id,S.contractQuantity);int pay=(int)(p.basePrice*S.contractQuantity*C.balance.economy.contractPriceFactor*(HasPartner(C.balance.partnerRoles.merchant)?C.balance.economy.contractPartnerFactor:1));S.gold+=pay;S.cities[S.city].reputation+=C.balance.economy.contractReputation;S.contracts++;S.contractProduct=(S.contractProduct+C.balance.economy.contractProductStep)%C.products.Length;S.contractDeadline=S.worldHours+C.balance.economy.contractHours;Emit("contract");return "商会支付 "+pay+" 金币，本城声望+"+C.balance.economy.contractReputation;}
}}
